package lesson

import (
	"fmt"
	"net/http"
)

type Greeter struct{ Prefix string }

func (g Greeter) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	fmt.Fprint(w, g.Prefix+" world")
}

func health(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusNoContent)
}
```

**handler_test.go**

```go
package lesson

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestHandlerForms(t *testing.T) {
	request := httptest.NewRequest(http.MethodGet, "/", nil)
	greeterResponse := httptest.NewRecorder()
	var greeter http.Handler = Greeter{Prefix: "hello"}
	greeter.ServeHTTP(greeterResponse, request)
	if greeterResponse.Body.String() != "hello world" {
		t.Fatal(greeterResponse.Body.String())
	}
	healthResponse := httptest.NewRecorder()
	http.HandlerFunc(health).ServeHTTP(healthResponse, request)
	if healthResponse.Code != http.StatusNoContent {
		t.Fatal(healthResponse.Code)
	}
}
```

**Run it**

```bash
go test -race ./...
go vet ./...
```

The compiler accepts both values as `http.Handler`, so the caller uses the same `ServeHTTP` operation for either implementation.

