package lesson

import (
	"fmt"
	"net/http"
	"sync/atomic"
)

type CounterHandler struct{ total atomic.Int64 }

func (h *CounterHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	fmt.Fprint(w, h.total.Add(1))
}

func (h *CounterHandler) Total() int64 { return h.total.Load() }
```

**counter_test.go**

```go
package lesson

import (
	"net/http"
	"net/http/httptest"
	"sync"
	"testing"
)

func TestConcurrentRequests(t *testing.T) {
	handler := &CounterHandler{}
	const requests = 40
	var group sync.WaitGroup
	for range requests {
		group.Add(1)
		go func() {
			defer group.Done()
			handler.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest(http.MethodGet, "/", nil))
		}()
	}
	group.Wait()
	if handler.Total() != requests {
		t.Fatalf("total=%d; want %d", handler.Total(), requests)
	}
}
```

**Run it**

```bash
go test -race ./...
go vet ./...
```

The shared counter has one explicit atomic policy. Each recorder and request remains local to one goroutine.
